{{-- Supplier card (reference UI.supplierCard) --}}
<a class="sup-card" href="{{ route('suppliers.show', $s) }}"><div class="logo-tile" style="background:{{ $s->color }}1a">{{ $s->logo }}</div><div class="grow"><div class="strong">{{ $s->name }}</div><div class="small muted">{{ $s->city }} · {{ $s->fulfillmentLabel() }}</div><div class="small"><span class="stars">★</span> {{ $s->rating ? rtrim(rtrim(number_format($s->rating, 1), '0'), '.') : '—' }} · {{ $s->products()->where('status', 'active')->where('package_only', false)->count() }} items</div></div>{{ icon('right', 'width:18px;color:var(--muted)') }}</a>
